//=============================================================================
// MeikohanaStorageMZ.js
//=============================================================================
/*:
 * @target MZ
 * @plugindesc v1.5.0 Penyimpanan save game ke folder bertingkat (RPGMakerSaves/NamaGame) dengan proteksi AES-CBC + HMAC-SHA256 untuk RPG Maker MZ
 * @author Iio Meko (Converted to MZ)
 *
 * @param SaveFolder
 * @text Nama Folder Utama
 * @desc Folder utama di Android. Di dalamnya akan otomatis dibuat folder baru sesuai judul game.
 * @default RPGMakerSaves
 *
 * @param Directory
 * @text Direktori Penyimpanan
 * @desc DOCUMENTS, DATA, EXTERNAL, EXTERNAL_STORAGE, CACHE
 * @default DOCUMENTS
 *
 * @param DebugMode
 * @text Mode Debug
 * @desc Tampilkan log debug di console
 * @type boolean
 * @default false
 *
 * @param MaxWaitMs
 * @text Maks Waktu Tunggu Capacitor (ms)
 * @desc Berapa lama menunggu Capacitor siap sebelum timeout (default 5000)
 * @type number
 * @default 5000
 *
 * @param EncryptSaves
 * @text Aktifkan Proteksi
 * @desc Enkripsi + tanda tangan save (AES-CBC + HMAC-SHA256). Save jadi tidak terbaca & tidak bisa diedit.
 * @type boolean
 * @default true
 *
 * @param EncryptionPassword
 * @text Kata Sandi Proteksi
 * @desc WAJIB DIGANTI sebelum release! Minimal 16 karakter, makin panjang & acak makin baik.
 * @default GANTI_INI_SEBELUM_RELEASE_PAKE_STRING_ACAK_YANG_PANJANG_DAN_UNIK
 *
 * @param AllowLegacyLoad
 * @text Izinkan Load Save Lama
 * @desc Jika true, save lama (belum terproteksi) tetap bisa di-load lalu otomatis diproteksi saat disimpan ulang.
 * @type boolean
 * @default true
 *
 * @help
 * ============================================================================
 * Plugin ini mengarahkan penyimpanan save game RPG Maker MZ
 * ke folder lokal Android melalui Capacitor Filesystem API,
 * dengan proteksi enkripsi + tanda tangan (anti-edit).
 *
 * PROTEKSI:
 * - AES-CBC 256-bit untuk enkripsi (isi save tidak terbaca).
 * - HMAC-SHA256 untuk autentikasi (encrypt-then-MAC) — kalau file
 *   diedit walau 1 byte, HMAC tidak cocok dan load ditolak.
 * - Kunci AES dan kunci HMAC diturunkan terpisah dari kata sandi
 *   via PBKDF2 (100.000 iterasi, SHA-256).
 * - Semua via Web Crypto API native — tidak butuh library tambahan.
 *
 * Format file terproteksi (binary, di-base64-kan):
 *   [MAGIC 4B "MK02"][SALT 16B][IV 16B][HMAC 32B][CIPHERTEXT...]
 *
 * PENTING:
 * - WAJIB ganti EncryptionPassword sebelum release.
 * - Jangan ganti password setelah game dirilis — semua save player
 *   yang sudah ada akan tidak bisa di-load lagi.
 * - Proteksi ini sisi-klien: kunci ada di APK, jadi menghalangi
 *   modifikasi save, bukan reverse engineering total.
 * ============================================================================
 */

(function () {
    'use strict';

    // Fungsi pembersih nama folder agar aman dari karakter yang dilarang sistem operasi
    function sanitizeFolderName(name) {
        if (!name) return 'iiomekogame';
        // Ganti spasi dan karakter khusus dengan underscore (_)
        return name.replace(/[^a-zA-Z0-9_\-]/g, '_');
    }

    var parameters  = PluginManager.parameters('MeikohanaStorageMZ');
    // Fallback ke nama lama jika plugin dipasang dengan nama file berbeda
    if (!parameters || Object.keys(parameters).length === 0) {
        parameters = PluginManager.parameters('CapacitorStorageMZ') ||
                     PluginManager.parameters('CapacitorStorage') || {};
    }
    var MASTER_FOLDER = String(parameters['SaveFolder'] || 'iiomeko');
    var DIRECTORY     = String(parameters['Directory']  || 'DOCUMENTS');
    var DEBUG         = parameters['DebugMode'] === 'true';
    var MAX_WAIT_MS   = Number(parameters['MaxWaitMs']  || 5000);
    var ENCRYPT       = parameters['EncryptSaves'] !== 'false';
    var PASSWORD      = String(parameters['EncryptionPassword'] || '');
    var ALLOW_LEGACY  = parameters['AllowLegacyLoad'] !== 'false';

    // Deteksi judul game dari file HTML game Anda
    var gameTitle = document.title || 'iiomekogame';
    var SAFE_GAME_TITLE = sanitizeFolderName(gameTitle);

    // Menggabungkan menjadi struktur bertingkat: "RPGMakerSaves/Nama_Game"
    var SAVE_FOLDER = MASTER_FOLDER + '/' + SAFE_GAME_TITLE;

    //-------------------------------------------------------------------------
    // Utilitas
    //-------------------------------------------------------------------------

    function debugLog() {
        if (DEBUG) {
            var args = Array.prototype.slice.call(arguments);
            console.log.apply(console, ['[MeikohanaStorageMZ]'].concat(args));
        }
    }

    /** Apakah aplikasi berjalan di atas Capacitor native platform. */
    function isCapacitor() {
        return !!(
            window.Capacitor &&
            typeof window.Capacitor.isNativePlatform === 'function' &&
            window.Capacitor.isNativePlatform()
        );
    }

    /** Ambil objek Filesystem dari Capacitor global. */
    function getFS() {
        return (
            (window.Capacitor &&
             window.Capacitor.Plugins &&
             window.Capacitor.Plugins.Filesystem) ||
            null
        );
    }

    /** Apakah Capacitor Filesystem SUDAH tersedia. */
    function isCapacitorFSReady() {
        return !!getFS();
    }

    /** Kembalikan string direktori yang diterima Capacitor Filesystem API. */
    function getCapacitorDir() {
        var plugins = window.Capacitor && window.Capacitor.Plugins;
        if (plugins && plugins.FilesystemDirectory) {
            return plugins.FilesystemDirectory[DIRECTORY] ||
                   plugins.FilesystemDirectory.DOCUMENTS;
        }
        return DIRECTORY;
    }

    /** Polling hingga Capacitor Filesystem tersedia atau timeout tercapai. */
    function waitForCapacitorFS() {
        return new Promise(function (resolve) {
            if (isCapacitorFSReady()) {
                resolve(true);
                return;
            }

            var elapsed  = 0;
            var interval = 100; // cek setiap 100 ms

            var timer = setInterval(function () {
                elapsed += interval;

                if (isCapacitorFSReady()) {
                    clearInterval(timer);
                    debugLog('CapacitorFS siap setelah ' + elapsed + 'ms');
                    resolve(true);
                } else if (elapsed >= MAX_WAIT_MS) {
                    clearInterval(timer);
                    console.error(
                        '[MeikohanaStorageMZ] Timeout: Capacitor.Plugins.Filesystem tidak tersedia setelah ' + MAX_WAIT_MS + 'ms.'
                    );
                    resolve(false);
                }
            }, interval);
        });
    }

    //-------------------------------------------------------------------------
    // Crypto: AES-CBC 256-bit + HMAC-SHA256 (Encrypt-then-MAC)
    //-------------------------------------------------------------------------
    // Format file terproteksi:
    //   [MAGIC 4B "MK02"][SALT 16B][IV 16B][HMAC 32B][CIPHERTEXT...]
    // Lalu seluruhnya di-base64 agar aman ditulis sebagai utf8 ke filesystem.
    //
    // HMAC dihitung atas: MAGIC || SALT || IV || CIPHERTEXT
    // (encrypt-then-MAC, urutan yang aman). Saat load, HMAC diverifikasi
    // DULU sebelum dekripsi — kalau tidak cocok, langsung tolak.

    var MAGIC = new Uint8Array([0x4D, 0x4B, 0x30, 0x32]); // "MK02"

    function hasWebCrypto() {
        return !!(window.crypto && window.crypto.subtle);
    }

    if (ENCRYPT && !hasWebCrypto()) {
        console.warn('[MeikohanaStorageMZ] Web Crypto API tidak tersedia — proteksi dimatikan.');
        ENCRYPT = false;
    }

    // Cache kunci hasil PBKDF2 agar tidak diturunkan ulang per salt
    var aesKeyCache  = {};
    var hmacKeyCache = {};

    function strToBytes(str) { return new TextEncoder().encode(str); }
    function bytesToStr(bytes) { return new TextDecoder().decode(bytes); }

    function bytesToBase64(bytes) {
        var binary = '';
        var len = bytes.byteLength;
        for (var i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
        return btoa(binary);
    }

    function base64ToBytes(b64) {
        var binary = atob(b64);
        var len = binary.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) bytes[i] = binary.charCodeAt(i);
        return bytes;
    }

    function concatBytes(arrays) {
        var total = 0, i;
        for (i = 0; i < arrays.length; i++) total += arrays[i].length;
        var result = new Uint8Array(total);
        var offset = 0;
        for (i = 0; i < arrays.length; i++) {
            result.set(arrays[i], offset);
            offset += arrays[i].length;
        }
        return result;
    }

    function bytesEqual(a, b) {
        if (a.length !== b.length) return false;
        // Perbandingan constant-time untuk hindari timing attack pada HMAC
        var diff = 0;
        for (var i = 0; i < a.length; i++) diff |= (a[i] ^ b[i]);
        return diff === 0;
    }

    // Turunkan kunci (AES atau HMAC) dari password + salt via PBKDF2.
    // 'info' membedakan kunci AES vs HMAC walau password & salt sama.
    function deriveKey(salt, info) {
        var cacheKey = bytesToBase64(salt);
        var cache = (info === 'hmac') ? hmacKeyCache : aesKeyCache;
        if (cache[cacheKey]) return Promise.resolve(cache[cacheKey]);

        // Bedakan material dengan menambahkan 'info' ke password
        var pwBytes = strToBytes(PASSWORD + '::' + info);

        var algo, usages;
        if (info === 'hmac') {
            algo = { name: 'HMAC', hash: 'SHA-256' };
            usages = ['sign', 'verify'];
        } else {
            algo = { name: 'AES-CBC', length: 256 };
            usages = ['encrypt', 'decrypt'];
        }

        return window.crypto.subtle.importKey(
            'raw', pwBytes, { name: 'PBKDF2' }, false, ['deriveKey']
        ).then(function (baseKey) {
            return window.crypto.subtle.deriveKey(
                { name: 'PBKDF2', salt: salt, iterations: 100000, hash: 'SHA-256' },
                baseKey, algo, false, usages
            );
        }).then(function (key) {
            cache[cacheKey] = key;
            return key;
        });
    }

    // Enkripsi string -> base64 terproteksi
    function protect(plainStr) {
        var salt = window.crypto.getRandomValues(new Uint8Array(16));
        var iv   = window.crypto.getRandomValues(new Uint8Array(16));
        var aesKey, hmacKey;

        return deriveKey(salt, 'aes').then(function (k) {
            aesKey = k;
            return deriveKey(salt, 'hmac');
        }).then(function (k) {
            hmacKey = k;
            return window.crypto.subtle.encrypt(
                { name: 'AES-CBC', iv: iv }, aesKey, strToBytes(plainStr)
            );
        }).then(function (cipherBuf) {
            var ciphertext = new Uint8Array(cipherBuf);
            // HMAC atas MAGIC || SALT || IV || CIPHERTEXT
            var macInput = concatBytes([MAGIC, salt, iv, ciphertext]);
            return window.crypto.subtle.sign('HMAC', hmacKey, macInput)
                .then(function (macBuf) {
                    var hmac = new Uint8Array(macBuf); // 32 byte
                    var blob = concatBytes([MAGIC, salt, iv, hmac, ciphertext]);
                    return bytesToBase64(blob);
                });
        });
    }

    // Dekripsi base64 terproteksi -> string. Reject kalau HMAC tidak cocok.
    function unprotect(b64) {
        var blob = base64ToBytes(b64);
        var HEADER = 4 + 16 + 16 + 32; // MAGIC+SALT+IV+HMAC
        if (blob.length < HEADER) {
            return Promise.reject(new Error('File terlalu pendek untuk format terproteksi.'));
        }

        var magic      = blob.slice(0, 4);
        if (!bytesEqual(magic, MAGIC)) {
            return Promise.reject(new Error('MAGIC tidak cocok — bukan format MK02.'));
        }
        var salt       = blob.slice(4, 20);
        var iv         = blob.slice(20, 36);
        var hmac       = blob.slice(36, 68);
        var ciphertext = blob.slice(68);

        var aesKey;
        return deriveKey(salt, 'aes').then(function (k) {
            aesKey = k;
            return deriveKey(salt, 'hmac');
        }).then(function (hmacKey) {
            // Verifikasi HMAC DULU sebelum dekripsi
            var macInput = concatBytes([MAGIC, salt, iv, ciphertext]);
            return window.crypto.subtle.sign('HMAC', hmacKey, macInput);
        }).then(function (macBuf) {
            var expected = new Uint8Array(macBuf);
            if (!bytesEqual(expected, hmac)) {
                throw new Error('HMAC tidak cocok — save dimodifikasi atau rusak.');
            }
            return window.crypto.subtle.decrypt(
                { name: 'AES-CBC', iv: iv }, aesKey, ciphertext
            );
        }).then(function (plainBuf) {
            return bytesToStr(new Uint8Array(plainBuf));
        });
    }

    // Jika tidak di Capacitor, biarkan StorageManager bawaan bekerja (untuk Playtest di PC)
    if (!isCapacitor()) {
        debugLog('Tidak berjalan di Capacitor — menggunakan StorageManager default.');
        return;
    }

    if (ENCRYPT && PASSWORD.indexOf('GANTI_INI') === 0) {
        console.warn(
            '[MeikohanaStorageMZ] PERINGATAN: EncryptionPassword masih default. ' +
            'Wajib ganti di Plugin Manager sebelum release game!'
        );
    }
    if (ENCRYPT && PASSWORD.length < 16) {
        console.warn(
            '[MeikohanaStorageMZ] PERINGATAN: EncryptionPassword terlalu pendek (<16 karakter).'
        );
    }

    debugLog('Capacitor terdeteksi, folder save diarahkan ke: ' + SAVE_FOLDER);
    debugLog('Proteksi:', ENCRYPT ? 'AKTIF (AES-CBC + HMAC-SHA256)' : 'NONAKTIF');

    //-------------------------------------------------------------------------
    // StorageManager Overrides (Khusus RPG Maker MZ)
    //-------------------------------------------------------------------------

    StorageManager.isLocalMode = function () {
        return true;
    };

    // Override path penyimpanan utama menggunakan format MZ (.rmmzsave)
    StorageManager.filePath = function (saveName) {
        return SAVE_FOLDER + '/' + saveName + '.rmmzsave';
    };

    // Deteksi apakah string adalah data terproteksi format kita.
    // Data zip MZ valid diawali pola tertentu; data terproteksi adalah base64
    // dari blob yang diawali MAGIC "MK02". Kita cek dengan decode prefix.
    function looksProtected(str) {
        if (!str || str.length < 8) return false;
        try {
            // 4 byte pertama MAGIC -> base64 dari "MK02" = "TUswMg" (prefix)
            // Lebih aman: decode sedikit lalu cek MAGIC.
            var head = base64ToBytes(str.slice(0, 8));
            return head.length >= 4 &&
                   head[0] === MAGIC[0] && head[1] === MAGIC[1] &&
                   head[2] === MAGIC[2] && head[3] === MAGIC[3];
        } catch (e) {
            return false;
        }
    }

    // --- WRITE ---

    StorageManager.saveToLocalFile = function (saveName, zip) {
        var fs = getFS();
        if (!fs) {
            return Promise.reject(new Error('[MeikohanaStorageMZ] Filesystem belum siap saat saveToLocalFile dipanggil.'));
        }

        var filePath = this.filePath(saveName);
        debugLog('Saving to:', filePath, ENCRYPT ? '(terproteksi)' : '(plain)');

        // MZ mengirim 'zip' berupa string. Kita proteksi (opsional) sebelum tulis.
        var prepare = ENCRYPT ? protect(zip) : Promise.resolve(zip);

        return prepare.then(function (dataToWrite) {
            return fs.mkdir({
                path:      SAVE_FOLDER,
                directory: getCapacitorDir(),
                recursive: true
            }).catch(function () {
                // folder sudah ada = abaikan error
            }).then(function () {
                return fs.writeFile({
                    path:      filePath,
                    data:      dataToWrite,
                    directory: getCapacitorDir(),
                    encoding:  'utf8'
                });
            });
        }).then(function (result) {
            // Simpan 'zip' BERSIH (belum diproteksi) di cache agar load instan
            // mengembalikan data yang langsung bisa di-unzip MZ.
            StorageManager._loadCache[saveName] = zip;
            debugLog('Save sukses:', filePath);
            return result;
        }).catch(function (err) {
            console.error('[MeikohanaStorageMZ] Save gagal:', err);
            throw err;
        });
    };

    // --- READ ---

    StorageManager.loadFromLocalFile = function (saveName) {
        var cached = StorageManager._loadCache[saveName];
        if (cached !== undefined) {
            if (cached === null) {
                return Promise.reject(new Error("File tidak ditemukan di cache"));
            }
            return Promise.resolve(cached);
        }

        var fs = getFS();
        if (!fs) {
            return Promise.reject(new Error('[MeikohanaStorageMZ] Filesystem belum siap saat loadFromLocalFile dipanggil.'));
        }

        var filePath = this.filePath(saveName);
        debugLog('Loading from:', filePath);

        return fs.readFile({
            path:      filePath,
            directory: getCapacitorDir(),
            encoding:  'utf8'
        }).then(function (result) {
            var raw = result.data;
            if (raw === undefined || raw === null || raw === '') {
                throw new Error('File save kosong: ' + saveName);
            }

            if (looksProtected(raw)) {
                // File terproteksi — verifikasi HMAC & dekripsi
                return unprotect(raw).catch(function (err) {
                    console.error('[MeikohanaStorageMZ] Proteksi gagal untuk', saveName, '—', err.message || err);
                    throw new Error('Save tidak valid atau dimodifikasi: ' + saveName);
                });
            }

            // File lama (belum terproteksi) — kembalikan apa adanya kalau diizinkan
            if (!ALLOW_LEGACY && ENCRYPT) {
                throw new Error('Save tidak terproteksi & AllowLegacyLoad=false: ' + saveName);
            }
            debugLog('Load legacy (belum terproteksi):', saveName);
            return raw; // Biarkan MZ menangani unzip internalnya sendiri
        }).catch(function (err) {
            debugLog('Load info (mungkin belum ada):', err.message || err);
            throw err;
        });
    };

    StorageManager._loadCache = {};

    StorageManager.preloadAllSaves = function () {
        if (!isCapacitorFSReady()) {
            debugLog('preloadAllSaves dipanggil tapi Filesystem belum siap — dilewati.');
            return Promise.resolve();
        }

        var self     = this;
        var promises = [];

        // Preload config dan global
        ["config", "global"].forEach(function (saveName) {
            promises.push(
                self.loadFromLocalFile(saveName).then(function (data) {
                    StorageManager._loadCache[saveName] = data;
                }).catch(function () {
                    StorageManager._loadCache[saveName] = null;
                })
            );
        });

        // Preload file0 (autosave) s/d fileN (manual save)
        for (var i = 0; i <= DataManager.maxSavefiles(); i++) {
            var saveName = DataManager.makeSavename(i);
            (function (name) {
                promises.push(
                    self.loadFromLocalFile(name).then(function (data) {
                        StorageManager._loadCache[name] = data;
                    }).catch(function () {
                        StorageManager._loadCache[name] = null;
                    })
                );
            })(saveName);
        }

        return Promise.all(promises);
    };

    // --- EXISTS ---

    StorageManager.localFileExists = function (saveName) {
        return !!StorageManager._loadCache[saveName];
    };

    StorageManager.exists = function (saveName) {
        return this.localFileExists(saveName);
    };

    // --- DELETE ---

    StorageManager.removeLocalFile = function (saveName) {
        var fs = getFS();
        if (!fs) {
            return Promise.resolve();
        }

        var filePath = this.filePath(saveName);
        debugLog('Removing:', filePath);

        return fs.deleteFile({
            path:      filePath,
            directory: getCapacitorDir()
        }).then(function () {
            delete StorageManager._loadCache[saveName];
            debugLog('File dihapus:', filePath);
        }).catch(function (err) {
            console.error('[MeikohanaStorageMZ] Remove gagal:', err);
        });
    };

    // --- MKDIR ---

    StorageManager.ensureFolder = function () {
        var fs = getFS();
        if (!fs) {
            return Promise.reject(new Error('[MeikohanaStorageMZ] Filesystem belum siap saat ensureFolder dipanggil.'));
        }

        return fs.mkdir({
            path:      SAVE_FOLDER,
            directory: getCapacitorDir(),
            recursive: true
        }).catch(function (err) {
            debugLog('mkdir info (mungkin sudah ada):', err.message || err);
        });
    };

    //-------------------------------------------------------------------------
    // DataManager — pastikan savefileExists memakai cache kita
    //-------------------------------------------------------------------------
    // Di MZ, Window_SavefileList menampilkan slot berdasarkan DataManager._globalInfo,
    // yang diisi oleh loadGlobalInfo() (async, via StorageManager.loadObject).
    // Karena kita preload "global" ke _loadCache lebih dulu di Scene_Boot, lalu
    // memanggil ulang loadGlobalInfo() bawaan MZ setelah cache siap, daftar slot
    // akan benar sejak cold start. Kita TIDAK mengganti implementasi loadGlobalInfo
    // bawaan — cukup memastikan savefileExists memakai jalur cache kita.

    DataManager.savefileExists = function (savefileId) {
        var saveName = this.makeSavename(savefileId);
        return StorageManager.exists(saveName);
    };

    //-------------------------------------------------------------------------
    // Scene_Boot — tunggu CapacitorFS siap SEBELUM preload selesai
    //-------------------------------------------------------------------------

    var _Scene_Boot_create = Scene_Boot.prototype.create;
    Scene_Boot.prototype.create = function () {
        _Scene_Boot_create.call(this);

        this._capacitorReady = false;
        var self = this;

        waitForCapacitorFS().then(function (ready) {
            if (!ready) {
                return; // _capacitorReady di-set true di finally
            }

            return StorageManager.ensureFolder()
                .then(function () {
                    return StorageManager.preloadAllSaves();
                })
                .then(function () {
                    debugLog('Semua save berhasil di-preload.');

                    // Muat ulang ConfigManager dari cache yang sudah terisi
                    if (typeof ConfigManager !== 'undefined' && typeof ConfigManager.load === 'function') {
                        ConfigManager.load();
                    }

                    // PENTING: panggil ulang loadGlobalInfo() BAWAAN MZ sekarang,
                    // setelah _loadCache["global"] terisi. loadGlobalInfo akan membaca
                    // lewat StorageManager (yang kini mengembalikan data dari cache),
                    // lalu mengisi DataManager._globalInfo. Tanpa ini, daftar slot
                    // tampak kosong pada cold start pertama (race condition).
                    if (typeof DataManager !== 'undefined' &&
                        typeof DataManager.loadGlobalInfo === 'function') {
                        try {
                            DataManager.loadGlobalInfo();
                            debugLog('loadGlobalInfo() dipanggil ulang setelah preload.');
                        } catch (e) {
                            debugLog('loadGlobalInfo gagal:', e.message || e);
                        }
                    }
                })
                .catch(function (err) {
                    console.error('[MeikohanaStorageMZ] Preload error:', err);
                });
        }).catch(function (err) {
            console.error('[MeikohanaStorageMZ] Boot init error:', err);
        }).finally(function () {
            self._capacitorReady = true;
        });
    };

    var _Scene_Boot_isReady = Scene_Boot.prototype.isReady;
    Scene_Boot.prototype.isReady = function () {
        return _Scene_Boot_isReady.call(this) && !!this._capacitorReady;
    };

})();